#include "ppg_ibi.h"
#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define M5_MAX_EVENTS 10000u
#define M5_MATCH_WINDOW_MS 500u

typedef struct { uint32_t timestamp_ms; uint16_t ibi_ms; float confidence; uint32_t flags; ppg_ibi_state_t state; } pred_t;
typedef struct { uint32_t timestamp_ms; uint16_t ibi_ms; } truth_t;
typedef struct { uint32_t truth_count,pred_count,matched_count,miss_count,extra_count; float mae_ms,mean_error_ms,rmse_ms,max_abs_error_ms,p95_abs_error_ms; } met_t;
static int u32p(const char*s,uint32_t*o){char*e;unsigned long v=strtoul(s,&e,10);if(s==e||*e) return -1;*o=(uint32_t)v;return 0;}
static int i32p(const char*s,int32_t*o){char*e;long v=strtol(s,&e,10);if(s==e||*e) return -1;*o=(int32_t)v;return 0;}
static int metrics(const pred_t*p,uint32_t pc,const truth_t*t,uint32_t tc,met_t*m){bool used[M5_MAX_EVENTS]={0};float ae[M5_MAX_EVENTS];uint32_t mc=0;float as=0,es=0,ss=0,mx=0;for(uint32_t i=0;i<pc;i++){uint32_t bj=M5_MAX_EVENTS,bd=0xffffffffu;for(uint32_t j=0;j<tc;j++){if(used[j])continue;uint32_t dt=p[i].timestamp_ms>t[j].timestamp_ms?p[i].timestamp_ms-t[j].timestamp_ms:t[j].timestamp_ms-p[i].timestamp_ms;if(dt<=M5_MATCH_WINDOW_MS&&dt<bd){bd=dt;bj=j;}}if(bj<M5_MAX_EVENTS){int32_t e=(int32_t)p[i].ibi_ms-(int32_t)t[bj].ibi_ms;float a=fabsf((float)e);used[bj]=true;ae[mc++]=a;as+=a;es+=(float)e;ss+=(float)e*(float)e;if(a>mx)mx=a;}}
m->truth_count=tc;m->pred_count=pc;m->matched_count=mc;m->miss_count=tc-mc;m->extra_count=pc-mc;if(mc==0){m->mae_ms=m->mean_error_ms=m->rmse_ms=m->max_abs_error_ms=m->p95_abs_error_ms=0;return 0;}m->mae_ms=as/mc;m->mean_error_ms=es/mc;m->rmse_ms=sqrtf(ss/mc);m->max_abs_error_ms=mx;for(uint32_t i=0;i<mc;i++)for(uint32_t j=i+1;j<mc;j++)if(ae[j]<ae[i]){float x=ae[i];ae[i]=ae[j];ae[j]=x;}uint32_t idx=(mc*95u+99u)/100u;if(!idx)idx=1;m->p95_abs_error_ms=ae[idx-1];return 0;}
static int run_file(FILE*fp,pred_t*p,uint32_t*pc,truth_t*t,uint32_t*tc){char line[512];ppg_ibi_context_t ctx;ppg_ibi_output_t out;bool hdr=false;if(ppg_ibi_init(&ctx,NULL)!=PPG_IBI_STATUS_OK)return -1;while(fgets(line,sizeof(line),fp)){char*tok[7];unsigned n=0;char*cur=strtok(line,",\r\n");if(!cur)continue;if(!hdr){if(strcmp(cur,"timestamp_ms")!=0)return -2;hdr=true;continue;}tok[n++]=cur;while(n<7u&&(cur=strtok(NULL,",\r\n")))tok[n++]=cur;if(n<7u)continue;uint32_t ts,allow,ecg;int32_t v0,v1,v2,v3;if(u32p(tok[0],&ts)||i32p(tok[1],&v0)||i32p(tok[2],&v1)||i32p(tok[3],&v2)||i32p(tok[4],&v3)||u32p(tok[5],&allow)||u32p(tok[6],&ecg)||allow>1||ecg>65535)continue;ppg_ibi_input_t in={ts,{v0,v1,v2,v3},allow==1};if(ppg_ibi_process(&ctx,&in,&out)!=PPG_IBI_STATUS_OK)return -3;if(out.valid){if(*pc>=M5_MAX_EVENTS)return -4;p[(*pc)++]=(pred_t){ts,out.ibi_ms,out.confidence,out.flags,out.state};}if(ecg>0){if(*tc>=M5_MAX_EVENTS)return -5;t[(*tc)++]=(truth_t){ts,(uint16_t)ecg};}}return hdr?0:-6;}
static int self_case(uint16_t ibi,const char*name){ppg_ibi_context_t ctx;ppg_ibi_output_t out;pred_t p[M5_MAX_EVENTS];truth_t t[M5_MAX_EVENTS];met_t m;uint32_t pc=0,tc=0,ts=0,spb=ibi/20;ppg_ibi_init(&ctx,NULL);for(uint32_t i=0;i<16u*50u;i++){uint32_t ph=i%spb;float x=(float)ph/(float)spb;float pulse=1.0f-fabsf(2*x-1.0f);int32_t raw=(int32_t)(100000+24000*pulse);ppg_ibi_input_t in={ts,{raw,raw+8,raw-6,raw+3},true};ppg_ibi_process(&ctx,&in,&out);if(out.valid)p[pc++]=(pred_t){ts,out.ibi_ms,out.confidence,out.flags,out.state};if(i>0&&ph==0)t[tc++]=(truth_t){ts,ibi};ts+=20;}metrics(p,pc,t,tc,&m);printf("M5 self-test %s: matched=%u mae_ms=%.1f max_abs_error_ms=%.1f %s\n",name,m.matched_count,m.mae_ms,m.max_abs_error_ms,(m.matched_count>=3&&m.mae_ms<=120&&m.max_abs_error_ms<=200)?"pass":"fail");return (m.matched_count>=3&&m.mae_ms<=120&&m.max_abs_error_ms<=200)?0:1;}
int main(int argc,char**argv){if(argc==2&&strcmp(argv[1],"--self-test")==0){int r1=self_case(1000,"60bpm"),r2=self_case(800,"75bpm");puts((r1||r2)?"M5 self-test failed.":"M5 self-test passed.");return (r1||r2)?1:0;}if(argc!=2&&argc!=3){fprintf(stderr,"usage: %s --self-test | %s input.csv [output_prefix]\n",argv[0],argv[0]);return 2;}pred_t p[M5_MAX_EVENTS];truth_t t[M5_MAX_EVENTS];met_t m;uint32_t pc=0,tc=0;FILE*fp=fopen(argv[1],"r");if(!fp)return 3;int r=run_file(fp,p,&pc,t,&tc);fclose(fp);if(r)return 4;metrics(p,pc,t,tc,&m);printf("truth_count=%u\npred_count=%u\nmatched_count=%u\nmiss_count=%u\nextra_count=%u\nmae_ms=%.3f\nmean_error_ms=%.3f\nrmse_ms=%.3f\nmax_abs_error_ms=%.3f\np95_abs_error_ms=%.3f\n",m.truth_count,m.pred_count,m.matched_count,m.miss_count,m.extra_count,m.mae_ms,m.mean_error_ms,m.rmse_ms,m.max_abs_error_ms,m.p95_abs_error_ms);if(argc==3){char a[256],b[256];snprintf(a,sizeof(a),"%s_predictions.csv",argv[2]);snprintf(b,sizeof(b),"%s_metrics.csv",argv[2]);FILE*fa=fopen(a,"w");if(!fa)return 6;fprintf(fa,"timestamp_ms,ibi_ms,confidence,state,flags\n");for(uint32_t i=0;i<pc;i++)fprintf(fa,"%u,%u,%.6f,%d,%u\n",p[i].timestamp_ms,p[i].ibi_ms,p[i].confidence,(int)p[i].state,p[i].flags);fclose(fa);FILE*fb=fopen(b,"w");if(!fb)return 6;fprintf(fb,"truth_count,pred_count,matched_count,miss_count,extra_count,mae_ms,mean_error_ms,rmse_ms,max_abs_error_ms,p95_abs_error_ms\n");fprintf(fb,"%u,%u,%u,%u,%u,%.3f,%.3f,%.3f,%.3f,%.3f\n",m.truth_count,m.pred_count,m.matched_count,m.miss_count,m.extra_count,m.mae_ms,m.mean_error_ms,m.rmse_ms,m.max_abs_error_ms,m.p95_abs_error_ms);fclose(fb);}return 0;}
